import fse from 'fs-extra';
import os from 'os';
import path from 'path';
import { rewriteCssUrls } from '../local-preview/export-assets.js';
import { applyBasePathToExport, findBasePathConflict, normalizeExportBasePath, prefixNextAssetPaths, prefixNextStaticPaths, prefixNextStaticPathsInPayload, } from '../local-preview/export-base-path.js';
import { generateExportLlmsTxt } from '../local-preview/export-llms.js';
const push = (payload) => `<script>self.__next_f.push(${JSON.stringify([1, payload])})</script>`;
const readPayload = (html) => [...html.matchAll(/self\.__next_f\.push\((\[1,".*?"\])\)<\/script>/g)]
    .map((match) => {
    const parsed = JSON.parse(match[1] ?? '');
    return Array.isArray(parsed) && typeof parsed[1] === 'string' ? parsed[1] : '';
})
    .join('');
describe('normalizeExportBasePath', () => {
    it.each([
        [undefined, ''],
        ['', ''],
        ['/', ''],
        ['docs', '/docs'],
        ['/docs/', '/docs'],
        ['/docs/v1', '/docs/v1'],
    ])('normalizes %s to %s', (input, expected) => {
        expect(normalizeExportBasePath(input)).toBe(expected);
    });
    it.each(['/docs/../etc', '/docs//v1', '/docs?x=1', '/my docs', '/do"cs'])('rejects %s', (input) => {
        expect(() => normalizeExportBasePath(input)).toThrow('invalid base path');
    });
});
describe('findBasePathConflict', () => {
    it('returns the first page that starts with the base path', () => {
        expect(findBasePathConflict(['/', '/quickstart', '/docs/intro'], '/docs')).toBe('/docs/intro');
        expect(findBasePathConflict(['/', '/docs'], '/docs')).toBe('/docs');
    });
    it('ignores pages that only share a prefix, and exports without a base path', () => {
        expect(findBasePathConflict(['/docsearch', '/guides/docs'], '/docs')).toBeUndefined();
        expect(findBasePathConflict(['/docs/intro'], '')).toBeUndefined();
    });
});
describe('prefixNextAssetPaths', () => {
    it('prefixes chunk base and asset literals but not runtime concatenations', () => {
        const source = 'let t="/_next/",r=1;e.v("/_next/static/media/worker.js");x={path:"/_next/image"};let a=r.assetPrefix+"/_next/"+p';
        expect(prefixNextAssetPaths(source, '/docs')).toBe('let t="/docs/_next/",r=1;e.v("/docs/_next/static/media/worker.js");x={path:"/docs/_next/image"};let a=r.assetPrefix+"/_next/"+p');
    });
});
describe('prefixNextStaticPaths', () => {
    it('prefixes static attributes and flight chunk lists but not escaped text', () => {
        const html = [
            '<script src="/_next/static/chunks/a.js" async=""></script>',
            '<link rel="stylesheet" href="/docs/_next/static/css/b.css"/>',
            push('9:I[123,["/_next/static/chunks/a.js","/_next/static/chunks/c.js"],"default"]\n'),
            push('b:["$","code",null,{"children":"\\"/_next/static/chunks/escaped.js\\""}]\n'),
        ].join('');
        const result = prefixNextStaticPaths(html, '/docs');
        expect(result).toContain('<script src="/docs/_next/static/chunks/a.js"');
        expect(result).toContain('href="/docs/_next/static/css/b.css"');
        const payload = readPayload(result);
        expect(payload).toContain('9:I[123,["/docs/_next/static/chunks/a.js","/docs/_next/static/chunks/c.js"]');
        expect(payload).toContain('\\"/_next/static/chunks/escaped.js\\"');
    });
    it('leaves html untouched without a base path', () => {
        const html = '<script src="/_next/static/chunks/a.js"></script>' +
            push('9:I[1,["/_next/static/chunks/a.js"]]\n');
        expect(prefixNextStaticPaths(html, '')).toBe(html);
    });
});
describe('prefixNextStaticPathsInPayload', () => {
    it('prefixes chunk paths in a saved rsc payload but not escaped text', () => {
        const payload = `1:I[123,["/_next/static/chunks/a.js"],"default"]\n3:["$","p",null,{"children":"\\"/_next/static/x.js\\""}]\n`;
        expect(prefixNextStaticPathsInPayload(payload, '/docs')).toBe(payload.replace('["/_next/static/chunks/a.js"]', '["/docs/_next/static/chunks/a.js"]'));
        expect(prefixNextStaticPathsInPayload(payload, '')).toBe(payload);
    });
});
describe('applyBasePathToExport', () => {
    let exportDir;
    beforeEach(async () => {
        exportDir = await fse.mkdtemp(path.join(os.tmpdir(), 'mint-export-base-path-test-'));
    });
    afterEach(async () => {
        await fse.remove(exportDir);
    });
    it('patches html and turbopack chunks inside the export', async () => {
        await fse.outputFile(path.join(exportDir, 'guides', 'index.html'), '<script src="/_next/static/chunks/a.js"></script>');
        await fse.outputFile(path.join(exportDir, '_next', 'static', 'chunks', 'turbopack-1.js'), 'let t="/_next/";');
        await fse.outputFile(path.join(exportDir, 'images', 'app.js'), 'let t="/_next/";');
        await fse.outputFile(path.join(exportDir, 'guides', 'index.txt'), '1:I[1,["/_next/static/chunks/a.js"],"default"]\n');
        await applyBasePathToExport(exportDir, '/docs');
        await expect(fse.readFile(path.join(exportDir, 'guides', 'index.html'), 'utf8')).resolves.toBe('<script src="/docs/_next/static/chunks/a.js"></script>');
        await expect(fse.readFile(path.join(exportDir, '_next', 'static', 'chunks', 'turbopack-1.js'), 'utf8')).resolves.toBe('let t="/docs/_next/";');
        await expect(fse.readFile(path.join(exportDir, 'images', 'app.js'), 'utf8')).resolves.toBe('let t="/_next/";');
        await expect(fse.readFile(path.join(exportDir, 'guides', 'index.txt'), 'utf8')).resolves.toBe('1:I[1,["/docs/_next/static/chunks/a.js"],"default"]\n');
    });
});
describe('base path aware css and llms.txt', () => {
    it('makes root-relative urls in local css relative to the stylesheet', () => {
        const css = rewriteCssUrls('@font-face{src:url(/_next/static/media/inter.woff2)}', undefined, '/_next/static/chunks/app.css', () => undefined);
        expect(css).toBe('@font-face{src:url(../media/inter.woff2)}');
    });
    it('prefixes llms.txt links with the base path', () => {
        expect(generateExportLlmsTxt({ name: 'Conduit' }, [{ href: '/quickstart', title: 'Quickstart' }], ['/quickstart'], '/docs')).toBe('# Conduit\n\n## Docs\n\n- [Quickstart](/docs/quickstart)\n');
    });
});
